def step(self) -> None:
    # Example: Assume agents placed on a 2D grid, interact with neighbors only
    grid_size = int(self.population_size ** 0.5)
    agent_grid = np.array(self.agents).reshape((grid_size, grid_size))
    new_states = []
    updated_counts = {'S': 0, 'I': 0, 'R': 0}
    for i in range(grid_size):
        for j in range(grid_size):
            agent = agent_grid[i, j]
            if agent.state == 'S':
                # Check neighbors for infection
                infected_neighbors = 0
                for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < grid_size and 0 <= nj < grid_size:
                        if agent_grid[ni, nj].state == 'I':
                            infected_neighbors += 1
                prob_infection = 1 - (1 - self.beta) ** infected_neighbors
                if random.random() < prob_infection:
                    new_states.append('I')
                    updated_counts['I'] += 1
                else:
                    new_states.append('S')
                    updated_counts['S'] += 1
            elif agent.state == 'I':
                if random.random() < self.gamma:
                    new_states.append('R')
                    updated_counts['R'] += 1
                else:
                    new_states.append('I')
                    updated_counts['I'] += 1
            else:
                new_states.append('R')
                updated_counts['R'] += 1
    # Update agent states
    for (i, j), state in zip([(i, j) for i in range(grid_size) for j in range(grid_size)], new_states):
        agent_grid[i, j].state = state
    self.agents = list(agent_grid.flatten())
    self.curr_counts = updated_counts
